{"id": "negative-provider-summary-ko", "category": "negative", "language": "ko", "intent": "Summarize provider documentation", "expect": "no_trigger", "runs": 3, "threshold": 0.5, "context": {"files": [], "sources": ["https://example.com/provider-doc"]}, "prompt": "이 OpenAI 문서를 팀용 짧은 메모로 요약해줘. 스킬 폴더는 만들지 마.", "expected": {"must": ["hyper-skill를 사용하지 않음", "research 또는 docs 작업으로 처리", "skill folder output을 피함"], "mustNot": ["재사용 skill structure 생성", "SKILL.md 추가"]}, "metrics": ["triggerability", "scope", "source_boundary"]}
