{
  "model": "jev-latest",
  "state": {
    "ticket": "The export button returns a 500 error after a long report runs.",
    "history": [
      "report finished",
      "export clicked",
      "server error"
    ]
  },
  "questions": {
    "is_bug_report": {
      "type": "noul",
      "instructions": "Decide whether `state.ticket` reports a product defect rather than a question or a request.",
      "criteria": {
        "true": "The ticket describes behaviour that is broken.",
        "false": "The ticket asks for something new or asks a question."
      }
    },
    "category": {
      "type": "choice",
      "instructions": "Choose the single best category for `state.ticket`.",
      "criteria": {
        "billing": "About invoices or payments.",
        "export": "About producing or downloading a file.",
        "none": "No listed category fits."
      }
    },
    "severity": {
      "type": "score",
      "instructions": "Score how much of the product is unusable according to `state.ticket`.",
      "criteria": [
        "Cosmetic only.",
        "A single feature is degraded.",
        "A single feature is unusable.",
